    /** The standard days past its due date an invoice is given before it becomes overdue: a week's grace. */
    public static final int GRACE_DAYS = 7;

    /**
     * The annual late-interest rate this invoice is charged: its client's own, else the workspace's,
     * plus the premium in percentage points (for a HIGH payment risk client) when it is charged interest at
     * all, but no more than the legal maximum of the client's region.
     */
    public BigDecimal lateInterestRate(BigDecimal workspaceRate, BigDecimal premium) {
        BigDecimal rate = clientInterestRate == null ? workspaceRate : clientInterestRate;
        if (rate != null && rate.signum() > 0 && premium != null) {
            rate = rate.add(premium);
        }
        if (regionMaxInterest == null || rate == null) {
            return rate;
        }
        return rate.min(new BigDecimal(regionMaxInterest.trim()));
    }

    /**
     * Days past its due date this invoice is given before it becomes overdue: its client's grace
     * period, else their region's, else the standard week.
     */
    public int graceDays() {
        return clientGraceDays == null ? GRACE_DAYS : clientGraceDays;
    }

    /** The last day of the grace period after the given due date: {@link #graceDays()} days after it (see {@link #afterDays}). */
    private LocalDate graceEnd(LocalDate due) {
        return afterDays(due, graceDays());
    }

    /**
     * The day the given days of payment terms after from: business days when the workspace keeps a holiday
     * calendar, else calendar days.
     */
    private LocalDate afterDays(LocalDate from, int days) {
        Set<LocalDate> calendar = holidays == null ? null : holidays.isBlank() ? Set.of()
                : Arrays.stream(holidays.split(",")).map(d -> LocalDate.parse(d.trim())).collect(Collectors.toSet());
        return Holidays.after(from, days, calendar);
    }

    /**
     * The status on the given day once the given amount has been paid against the grand total at the
     * tax rate: a sent invoice with something still due more than {@link #graceDays()} days after its
     * due date is overdue, part paid or not. An invoice billed by milestones is instead overdue when any of its
     * milestones is (see {@link #milestoneProgress}).
     */
    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
        return statusWhenPaid(paid, null, taxRate, today);
    }

    /**
     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
     * paid date (null when not known) is after its due date is paid late.
     */
    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
        if (status != InvoiceStatus.SENT) {
            return status;
        }
        if (isWrittenOff()) {
            return InvoiceStatus.WRITTEN_OFF;
        }
        BigDecimal amountDue = amountDue(paid, taxRate);
        boolean due = amountDue.signum() > 0;
        BigDecimal disputed = disputedAmount(paid, taxRate);
        if (isWhollyDisputed() || (due && disputed.compareTo(amountDue) >= 0)) {
            return InvoiceStatus.DISPUTED;
        }
        boolean restDue = amountDue.subtract(disputed).signum() > 0;
        if (isBilledByMilestones()) {
            if (restDue && milestoneProgress(paid, taxRate, today).stream()
                    .anyMatch(p -> p.status() == Milestone.Status.OVERDUE)) {
                return InvoiceStatus.OVERDUE;
            }
        } else if (restDue && dueDate != null && today.isAfter(graceEnd(dueDate))) {
            return InvoiceStatus.OVERDUE;
        }
        if (!due && hasPendingMilestones()) {
            return InvoiceStatus.AWAITING_MILESTONE;
        }
        if (paid.signum() <= 0) {
            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
        }
        if (due) {
            return InvoiceStatus.PART_PAID;
        }
        LocalDate finalDue = isBilledByMilestones() ? milestones.stream().map(this::milestoneDueDate).filter(Objects::nonNull)
                        .max(Comparator.naturalOrder()).orElse(dueDate)
                : dueDate;
        return paidOn != null && finalDue != null && paidOn.isAfter(finalDue) ? InvoiceStatus.PAID_LATE
                : InvoiceStatus.PAID;
    }

    /**
     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
     * counts on the day it was applied); null while something is still due.
     */
    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
        BigDecimal total = payable(taxRate);
        if (status != InvoiceStatus.SENT || isWrittenOff() || total.signum() <= 0 || hasPendingMilestones()) {
            return null;
        }
        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
        }
        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
package net.officefloor.hq.app.invoices;

/**
 * Where an invoice is in its life: still being written, or sent to the client. A sent invoice is
 * part paid while some of it has been paid and some is still due, and paid once nothing is due, or
 * paid late when the payment that cleared it (taking payments in date order) came after its due date;
 * those follow from its payments and are never stored. A sent invoice with something still due
 * more than its client's grace period (a week unless set otherwise) after its due date is overdue, part paid or not; that follows from the date and is never stored.
 * A sent invoice with no payments can be voided: it is then void for good, owes nothing and takes no
 * payments or changes.
 * A credit note is a draft until it is issued, when it becomes CREDIT_NOTE for good. A sent invoice
 * whose issued credit notes leave nothing due, with nothing paid, is credited; that follows from its
 * credit notes and is never stored.
 * A sent invoice written off as a bad debt is written off for good: it owes nothing, earns no more
 * interest and takes no payments; that follows from the day it was written off.
 * A sent invoice in dispute is disputed until the dispute is resolved: it earns no interest, is not
 * overdue (a payment reaching it resolves the dispute); that follows from the days it was disputed and resolved.
 * A sent invoice billed by milestones with nothing owed now but milestones still to be reached is
 * awaiting a milestone; that follows from its milestones and payments and is never stored.
 */
public enum InvoiceStatus {
    DRAFT, SENT, PART_PAID, PAID, PAID_LATE, OVERDUE, VOID, CREDIT_NOTE, CREDITED, WRITTEN_OFF, DISPUTED, AWAITING_MILESTONE
}
